// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    function setUp() public { c = new Size(); }

    function testFuzz_property(address caller, address other, bytes32 role) public {
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);

        // General rule: renounceRole must revert if and only if the account being
        // renounced is NOT the caller; self-renunciation must always succeed
        // (regardless of role membership).

        // Direction 1: renouncing another account's role must revert.
        vm.prank(caller);
        bool okOther;
        try c.renounceRole(role, other) { okOther = true; } catch { okOther = false; }

        // Direction 2: renouncing one's own role must succeed.
        vm.prank(caller);
        bool okSelf;
        try c.renounceRole(role, caller) { okSelf = true; } catch { okSelf = false; }

        assertTrue(!okOther && okSelf);
    }
}
